import { memo, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

/**
 * Page-specific parking scenes. Each is an original, self-animating SVG generated by
 * apps/web/scripts/generate-backgrounds.py, with a static twin for reduced motion.
 */
export const SCENES = {
  login: { src: 'login/underground-garage', label: 'Underground parking garage' },
  driver: { src: 'driver/parking-deck', label: 'Parking deck' },
  parking: { src: 'parking/smart-lot-topdown', label: 'Smart parking lot' },
  owner: { src: 'owner/facility-infrastructure', label: 'Parking facility' },
  operator: { src: 'operator/monitored-deck', label: 'Monitored parking deck' },
  gate: { src: 'gate/automated-entrance', label: 'Automated parking entrance' },
  admin: { src: 'admin/mobility-control-room', label: 'Mobility control room' },
  ev: { src: 'ev-charging/ev-charging-hub', label: 'EV charging hub' }
};

const PAGE_SCENES = {
  'Find parking': 'parking',
  'Corporate & EV': 'ev',
  'Gate access': 'gate',
  'Gate hardware': 'gate',
  Operations: 'operator',
  'Camera detection': 'operator',
  'Plate recognition': 'operator',
  'Parking spaces': 'owner',
  'My listings': 'owner',
  'Owner earnings': 'owner',
  'Owner verification': 'owner',
  'Admin console': 'admin',
  'User management': 'admin',
  Promotions: 'admin',
  'Finance review': 'admin'
};

export function sceneForPage(page, { ownerWorkspace = false, isAdmin = false } = {}) {
  if (PAGE_SCENES[page]) return PAGE_SCENES[page];
  if (page === 'Overview') return isAdmin ? 'admin' : ownerWorkspace ? 'owner' : 'driver';
  return 'driver';
}

function PageBackdrop({ scene = 'driver', reduceMotion = false, intensity = 'page' }) {
  const systemReduce = useReducedMotion();
  const [failed, setFailed] = useState({});
  const def = SCENES[scene] ?? SCENES.driver;
  const still = reduceMotion || systemReduce;
  const src = `/assets/backgrounds/${def.src}${still ? '-static' : ''}.svg`;
  return (
    <div className={`sp-backdrop sp-backdrop-${intensity} scene-${scene}`} aria-hidden="true">
      <AnimatePresence initial={false}>
        {!failed[src] && (
          <motion.img
            key={src}
            className="sp-backdrop-img"
            src={src}
            alt=""
            decoding="async"
            initial={{ opacity: 0, scale: still ? 1 : 1.03 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: still ? 0 : 0.9, ease: [0.16, 1, 0.3, 1] }}
            onError={() => setFailed((f) => ({ ...f, [src]: true }))}
          />
        )}
      </AnimatePresence>
      <span className="sp-backdrop-overlay" />
    </div>
  );
}

export default memo(PageBackdrop);
